import importlib.util
from pathlib import Path

spec = importlib.util.spec_from_file_location('v8_screens', Path(__file__).resolve().parent.parent / 'HB-40-full-mockup/screens.py')
module = importlib.util.module_from_spec(spec)
spec.loader.exec_module(module)


