    def link(key, en, ko):
        return f'<a href="#auto-{key}">{t(en, ko)} →</a>'

    def table(head, rows):
        return '<div class="table-scroll" tabindex="0"><table><thead><tr>' + ''.join('<th>' + t(*h) + '</th>' for h in head) + '</tr></thead><tbody>' + ''.join('<tr>' + ''.join('<td>' + str(v) + '</td>' for v in row) + '</tr>' for row in rows) + '</tbody></table></div>'

