    body += table([('Step','단계'),('Observed design state','화면 상태 예시')],[[t('Automatic trigger','자동 실행 조건'),t('Source accepted or approved contract revision changed','원천 수용 또는 승인된 계약 버전 변경')],[t('Pinned inputs','고정 입력'),'SRC-OCT-S1 · LIST-OCT-L1 · PB-NS-R2 · NS-OCT-T1'],[t('Matching / calculation','매칭 / 계산'),t('3 synthetic charge groups · USD1,535 pretax','합성 비용 그룹 3개 · USD 1,535 세전')],[t('Retry identity','재시도 식별'),t('Same inputs reuse result; one-off grant not consumed twice','동일 입력은 결과 재사용 · 일회성 크레딧 중복 소진 안 함')],[t('Changed inputs','입력 변경'),t('New run revision; affected financial approval invalidated','새 실행 버전 · 영향받는 금액 승인 무효화')]])
    body += '<h2>'+t('Failure and recovery states','실패·복구 상태')+'</h2>'+table([('State','상태'),('Required action','필요한 처리')],[[t('Partial completion','일부 완료'),t('Keep per-customer results; blocked customers remain unissued','고객별 결과 보존 · 보류 고객은 미발행')],[t('Failed','실패'),t('Correct evidence and retry only affected targets','근거 수정 후 해당 대상만 재시도')],[t('Outcome unknown','결과 미확인'),t('Read back existing job/result before retry','기존 작업·결과 확인 후 재시도')]])
    body += link('trace','Inspect calculation evidence','계산 근거 확인')
    page('job','Automatic calculation and review','자동 계산·검수 상태',('Automatic pricing produces a reviewable revision; it does not issue an invoice.','자동 요율 적용은 검수 가능한 계산 버전을 만들며 인보이스를 발행하지 않습니다.'),body)

    body = table([('Charge / basis','비용 / 기준액'),('Selected rule','선택 규칙'),('Applied benefit','적용 혜택'),('Sales rule decision','영업 할인 판단'),('Result · USD','결과 · USD')],[['DB · 1,000.00','DB-10 · LIST-OCT-L1','BEN-DB-01 · −100.00',t('Excluded: SPECIAL_PRODUCT_PRICE','제외: SPECIAL_PRODUCT_PRICE'),'900.00'],['DTO · 200.00','DTO-20 · LIST-OCT-L1','BEN-DTO-01 · −40.00',t('Excluded: SPECIAL_PRODUCT_PRICE','제외: SPECIAL_PRODUCT_PRICE'),'160.00'],[t('Other eligible ·500.00','기타 적격 · 500.00'),'SALES-5 · LIST-OCT-L1','BEN-SALES-01 · −25.00',t('Applied to500 only','500에만 적용'),'475.00']])
    body += '<h2>'+t('Rule resolution and evidence','규칙 선택과 근거')+'</h2>'+table([('Field','항목'),('Value','내용')],[[t('Replaced / excluded candidates','대체 / 제외 후보'),t('DB and DTO exclude SALES-5; no competing exact-SKU rule in this case','DB·DTO는 SALES-5 제외 · 이 사례에는 경쟁하는 개별 SKU 규칙 없음')],[t('Original evidence','원천 근거'),'SRC-OCT-S1 · DEMO-DB-01 / DEMO-DTO-01 / DEMO-OTHER-01'],[t('Calculation / rounding','계산 / 반올림'),'1,700 −100 −40 −25 =1,535.00 · USD · '+t('line half-up,2 decimals','행별 소수 2자리 반올림')],[t('Supplier cost / margin','공급자 원가 / 마진'),t('Unavailable; not inferred','미조회 · 추정 안 함')],[t('Commitment or credit pools','약정·크레딧 집계'),t('None consumed in this case; future grants require fixed pool membership','이 사례에서는 소진 없음 · 적용 시 고정 집계 대상 필요')]])
    body += note('Filtering or paging does not change rule pools, tier thresholds or credit consumption. Unknown benefit provenance blocks the affected portion. Raw supplier data is never overwritten by a customer selling rule.','필터·페이지 이동은 집계 대상·구간 기준·크레딧 소진을 바꾸지 않습니다. 혜택 근거 미확인은 해당 비용을 보류합니다. 고객 판매 규칙으로 공급자 원천 데이터를 덮어쓰지 않습니다.')
    body += link('history','View version history','버전 이력 보기')
    page('trace','Explain every calculated price','자동 계산 요율·금액 근거',('Follow the matched rule from original charge to the final selling amount.','원천 비용부터 적용 규칙과 최종 판매 금액까지 추적합니다.'),body)

    body = table([('Revision','버전'),('State in example','예시 상태'),('Change','변경 내용'),('Amount · USD','금액 · USD'),('Approval','승인')],[['PB-NS-R1',t('Comparison baseline','비교 기준'),t('DB/DTO special rates; no general sales concession','DB·DTO 개별 요율 · 영업 할인 없음'),'1,560.00',t('Not an issuance approval','발행 승인 아님')],['PB-NS-R2',t('Proposed / preview complete','변경안 / 미리보기 완료'),t('SALES-5 on residual eligible charges only','나머지 적격 항목에만 SALES-5'),'1,535.00',t('Pending','대기')],[t('Scheduled state example','예약 상태 예시'),t('After activation review','활성화 검토 이후'),t('Northstar target only, effective time fixed','Northstar만 · 적용 시각 고정'),'—',t('Separate from financial approval','금액 승인과 별도')]])
    body += note('R1 and R2 compare identical October inputs, not September versus October usage. September issued documents are unchanged. After issuance, a late rate correction links to the original document and requires its own review.','R1·R2는 동일한 10월 입력을 비교하며 9월과 10월 사용량 비교가 아닙니다. 9월 발행 문서는 유지합니다. 발행 이후 요율 정정은 원문에 연결된 별도 검토 절차를 거칩니다.')
    body += link('rulebook','Return to current proposal','현재 변경안 보기')
    page('history','Contract and calculation history','계약·자동 계산 변경 이력',('Keep the rule, source and approval history behind each monthly calculation.','매월 계산에 사용한 규칙·원천·승인 이력을 보존합니다.'),body)

    body = metrics([(('Contract basis · USD','계약 기준액 · USD'),'1,700.00'),(('Product discounts','제품 할인'),'−140.00'),(('Sales concession','영업 할인'),'−25.00'),(('Estimated pretax','예상 세전 금액'),'1,535.00')])
    body += table([('Your charge','청구 항목'),('Contractual treatment','계약 적용'),('Sales discount','영업 할인'),('Amount · USD','금액 · USD')],[[t('DB-instance usage','DB 인스턴스 사용료'),t('10% off agreed list basis','합의한 정가 기준 10% 할인'),t('Excluded: product discount already applied','제품 할인 적용으로 제외'),'900.00'],[t('Eligible internet egress','적격 인터넷 송신'),t('20% off agreed list basis','합의한 정가 기준 20% 할인'),t('Excluded: product discount already applied','제품 할인 적용으로 제외'),'160.00'],[t('Other eligible usage','기타 적격 사용료'),t('5% sales concession','영업 할인 5%'),t('Applied','적용'),'475.00']])
    body += note('Northstar ·2026-10 · isolated customer-view example assuming the displayed selling terms have been approved. Estimated, not issued; tax and settlement are not included. This does not show an actual approval of the operator proposal. September records are separate.','Northstar · 2026-10 · 표시된 판매 조건이 승인된 경우를 가정한 독립 고객 화면 예시입니다. 예상 금액이며 미발행 상태로 세금·납부는 포함하지 않습니다. 운영자 변경안이 실제 승인됐다는 뜻이 아닙니다. 9월 기록과는 별개입니다.')
    body += '<p>'+t('Rate basis: agreed list price for the usage period. Discounts are calculated per charge and rounded to two USD decimals.','요율 기준: 사용 기간에 해당하는 합의된 정가입니다. 할인은 항목별 계산 후 USD 소수 2자리로 반올림합니다.')+'</p>'
    page('customer','How your contract determines your bill','내 계약 요율이 청구 금액에 반영되는 방식',('Northstar · October estimate · contractual selling prices only.','Northstar · 10월 예상 금액 · 고객 계약 판매 요율 기준'),body)
